import{c as e,S as l,j as r,m as a}from"./chunks/framework.8aa1YH_s.js";const u=JSON.parse('{"title":"Türk Dil Bilgisi Serisi - 9: Şekil Bilgisi - Eklerin Dünyası ve Yapım Ekleri","description":"","frontmatter":{},"headers":[],"relativePath":"9 Şekil Bilgisi - Eklerin Dünyası ve Yapım Ekleri.md","filePath":"9 Şekil Bilgisi - Eklerin Dünyası ve Yapım Ekleri.md"}'),n={name:"9 Şekil Bilgisi - Eklerin Dünyası ve Yapım Ekleri.md"};function m(k,i,s,t,d,o){return l(),r("div",null,[...i[0]||(i[0]=[a('<h1 id="turk-dil-bilgisi-serisi-9-sekil-bilgisi-eklerin-dunyası-ve-yapım-ekleri" tabindex="-1">Türk Dil Bilgisi Serisi - 9: Şekil Bilgisi - Eklerin Dünyası ve Yapım Ekleri <a class="header-anchor" href="#turk-dil-bilgisi-serisi-9-sekil-bilgisi-eklerin-dunyası-ve-yapım-ekleri" aria-label="Permalink to “Türk Dil Bilgisi Serisi - 9: Şekil Bilgisi - Eklerin Dünyası ve Yapım Ekleri”">​</a></h1><p>Bir önceki bölümümüzde Türkçede kelime köklerinin sabit olduğunu ve isim ile fiil olmak üzere iki ana gruba ayrıldığını görmüştük. Bu yazımızda ise bu köklere gelerek onlardan yeni kavramlar türeten, dilimizin kelime hazinesini ucu bucağı olmayan bir deryaya dönüştüren <strong>Yapım Ekleri</strong> konusunu ele alıyoruz.</p><p>Prof. Dr. Muharrem Ergin’e göre Türkçe, eklerinin zenginliği ve işlekliği sayesinde yabancı dillere ihtiyaç duymadan kendi kavramlarını üretebilen muazzam bir matematiksel yapıya sahiptir.</p><hr><h2 id="_1-ek-nedir-ve-turkcedeki-genel-ozellikleri" tabindex="-1">1. Ek Nedir ve Türkçedeki Genel Özellikleri? <a class="header-anchor" href="#_1-ek-nedir-ve-turkcedeki-genel-ozellikleri" aria-label="Permalink to “1. Ek Nedir ve Türkçedeki Genel Özellikleri?”">​</a></h2><p>Türkçede tek başlarına anlamları olmayan, ancak kelime kök ya da gövdelerine eklenerek yeni kelimeler türeten veya kelimelerin cümle içindeki görevlerini (çekimlerini) belirleyen ses yapılarına <strong>ek</strong> denir.</p><p>Muharrem Ergin sistematiğinde eklerin temel kuralları şunlardır:</p><ul><li><strong>Sona Eklenme:</strong> Türkçe asli yapısı gereği sondan eklemeli bir dildir. Ekler her zaman kökün veya gövdenin sağına (sonuna) gelir. Ön ek (<em>prefix</em>) asli Türkçede yoktur.</li><li><strong>Ses Uyumlarına Tabi Olma:</strong> Ekler, geldikleri kökün ünlü ve ünsüz yapısına göre şekil değiştirirler (<code>-lar/-ler</code>, <code>-cı/-ci/-cu/-cü</code> gibi).</li><li><strong>Sıralama Kuralı:</strong> Kelimeye önce <strong>Yapım Eki</strong>, daha sonra <strong>Çekim Eki</strong> gelir. <ul><li><em>Formül:</em> <code>Kök + Yapım Eki + Çekim Eki</code></li><li><em>Örnek:</em> <em>Göz</em> (Kök) + <em>-lük</em> (Yapım Eki) + <em>-ler</em> (Çekim Eki) = <strong>Gözlükler</strong></li></ul></li></ul><hr><h2 id="_2-yapım-ekleri-nedir" tabindex="-1">2. Yapım Ekleri Nedir? <a class="header-anchor" href="#_2-yapım-ekleri-nedir" aria-label="Permalink to “2. Yapım Ekleri Nedir?”">​</a></h2><p>Kök veya gövdelerin üzerine gelerek onlardan <strong>tamamen yeni ve farklı bir anlama sahip</strong> kelimeler türeten eklere <strong>Yapım Ekleri</strong> (Kelimeden Kelime Türetme Ekleri) denir.</p><p>Yapım ekleri eklendikleri kelimenin sadece anlamını değiştirmekle kalmaz, bazen türünü de (örneğin fiili isme, ismi fiile) değiştirebilirler. Yapım eki almış bir kelime artık bir <strong>gövde</strong>dir.</p><hr><h2 id="_3-yapım-eklerinin-sınıflandırılması" tabindex="-1">3. Yapım Eklerinin Sınıflandırılması <a class="header-anchor" href="#_3-yapım-eklerinin-sınıflandırılması" aria-label="Permalink to “3. Yapım Eklerinin Sınıflandırılması”">​</a></h2><p>Muharrem Ergin, Türkçedeki yapım eklerini, kelimenin başlangıçtaki kök türü ve eklendikten sonra dönüştüğü son türe göre <strong>4 ana gruba</strong> ayırır:</p><p>[ YAPIM EKLERİ ] | +--------------+-------+-------+--------------+ | | | | [ İ-İ ] [ İ-F ] [ F-İ ] [ F-F ]</p><h3 id="a-isimden-isim-yapım-ekleri-i-i" tabindex="-1">A) İsimden İsim Yapım Ekleri (İ-İ) <a class="header-anchor" href="#a-isimden-isim-yapım-ekleri-i-i" aria-label="Permalink to “A) İsimden İsim Yapım Ekleri (İ-İ)”">​</a></h3><p>İsim kök veya gövdelerine gelerek onlardan yeni bir isim türeten eklerdir. Kelimenin özü de isimdir, son hali de isimdir.</p><ul><li><strong>-lık / -lik / -luk / -lük (En işlek eklerden biridir):</strong><ul><li><em>Göz</em> (İsim) $$\\rightarrow$$ <em>Gözlük</em> (Yeni İsim)</li><li><em>Zeytin</em> (İsim) $$\\rightarrow$$ <em>Zeytinlik</em> (Yer ismi)</li></ul></li><li><strong>-cı / -ci / -cu / -cü (Meslek, alışkanlık ve ilgi bildirir):</strong><ul><li><em>Yol</em> (İsim) $$\\rightarrow$$ <em>Yolcu</em> (Yeni İsim)</li><li><em>Kitap</em> (İsim) $$\\rightarrow$$ <em>Kitapçı</em> (Meslek ismi)</li></ul></li><li><strong>-lı / -li / -lu / -lü (Sahiplik, aidiyet bildirir):</strong><ul><li><em>Ev</em> (İsim) $$\\rightarrow$$ <em>Evli</em> (Yeni İsim/Sıfat)</li><li><em>Tuz</em> (İsim) $$\\rightarrow$$ <em>Tuzlu</em> (Yeni İsim/Sıfat)</li></ul></li><li><strong>-sız / -siz / -suz / -süz (Olumsuzluk bildirir, &quot;-lı&quot; ekinin zıddıdır):</strong><ul><li><em>Su</em> (İsim) $$\\rightarrow$$ <em>Susuz</em></li></ul></li></ul><h3 id="b-isimden-fiil-yapım-ekleri-i-f" tabindex="-1">B) İsimden Fiil Yapım Ekleri (İ-F) <a class="header-anchor" href="#b-isimden-fiil-yapım-ekleri-i-f" aria-label="Permalink to “B) İsimden Fiil Yapım Ekleri (İ-F)”">​</a></h3><p>İsim kök veya gövdelerine gelerek onlardan bir eylem, hareket, yani fiil türeten eklerdir.</p><ul><li><strong>-la / -le (Çok işlektir):</strong><ul><li><em>Su</em> (İsim) $$\\rightarrow$$ <em>Sula-</em> (Fiil)</li><li><em>Göz</em> (İsim) $$\\rightarrow$$ <em>Gözle-</em> (Fiil)</li></ul></li><li><strong>-al / -el / -l (Oluş bildirir):</strong><ul><li><em>Çok</em> (İsim) $$\\rightarrow$$ <em>Çoğal-</em> (Fiil)</li><li><em>Düz</em> (İsim) $$\\rightarrow$$ <em>Düzel-</em> (Fiil)</li></ul></li><li><strong>-ar / -er (Renklerde ve oluşlarda kullanılır):</strong><ul><li><em>Sarı</em> (İsim) $$\\rightarrow$$ <em>Sarar-</em> (Fiil)</li><li><em>Yaş</em> (İsim) $$\\rightarrow$$ <em>Yeşer-</em> (Fiil)</li></ul></li></ul><h3 id="c-fiilden-isim-yapım-ekleri-f-i" tabindex="-1">C) Fiilden İsim Yapım Ekleri (F-İ) <a class="header-anchor" href="#c-fiilden-isim-yapım-ekleri-f-i" aria-label="Permalink to “C) Fiilden İsim Yapım Ekleri (F-İ)”">​</a></h3><p>Fiil kök veya gövdelerine gelerek hareket anlamını donduran ve onları birer isim, sıfat veya zarf haline getiren eklerdir.</p><ul><li><strong>-gı / -gi / -gu / -gü:</strong><ul><li><em>Sev-</em> (Fiil) $$\\rightarrow$$ <em>Sevgi</em> (İsim)</li><li><em>Sorgula-</em> (Fiil) $$\\rightarrow$$ <em>Sorgu</em> (İsim)</li></ul></li><li><strong>-ıcı / -ici (İşi yapanı bildirir):</strong><ul><li><em>Yaz-</em> (Fiil) $$\\rightarrow$$ <em>Yazıcı</em> (İsim)</li><li><em>Öğret-</em> (Fiil) $$\\rightarrow$$ <em>Öğretici</em> (İsim)</li></ul></li><li><strong>-ak / -ek:</strong><ul><li><em>Yat-</em> (Fiil) $$\\rightarrow$$ <em>Yatak</em> (İsim)</li><li><em>Dur-</em> (Fiil) $$\\rightarrow$$ <em>Durak</em> (İsim)</li></ul></li><li><strong>-ım / -im / -um / -üm:</strong><ul><li><em>Seç-</em> (Fiil) $$\\rightarrow$$ <em>Seçim</em> (İsim)</li><li><em>Üret-</em> (Fiil) $$\\rightarrow$$ <em>Üretim</em> (İsim)</li></ul></li></ul><h3 id="d-fiilden-fiil-yapım-ekleri-f-f" tabindex="-1">D) Fiilden Fiil Yapım Ekleri (F-F) <a class="header-anchor" href="#d-fiilden-fiil-yapım-ekleri-f-f" aria-label="Permalink to “D) Fiilden Fiil Yapım Ekleri (F-F)”">​</a></h3><p>Fiil kök veya gövdelerine gelerek eylemin yönünü, yapılış şeklini veya çatısını değiştiren, ancak onu yine bir fiil olarak bırakan eklerdir.</p><ul><li><strong>-ş (İşteşlik - Karşılıklı veya birlikte yapma bildirir):</strong><ul><li><em>Gör-</em> (Fiil) $$\\rightarrow$$ <em>Görüş-</em> (Yeni Fiil)</li><li><em>Gül-</em> (Fiil) $$\\rightarrow$$ <em>Gülüş-</em> (Yeni Fiil)</li></ul></li><li><strong>-t (Ettirgenlik / Oldurganlık bildirir):</strong><ul><li><em>Yürü-</em> (Fiil) $$\\rightarrow$$ <em>Yürüt-</em> (Yeni Fiil)</li><li><em>Kurut-</em> (Fiil) $$\\rightarrow$$ <em>Kurut-</em> (Yeni Fiil)</li></ul></li><li><strong>-ıl / -il / -ul / -ül (Edilgenlik bildirir):</strong><ul><li><em>Yap-</em> (Fiil) $$\\rightarrow$$ <em>Yapıl-</em> (Yeni Fiil)</li><li><em>Yaz-</em> (Fiil) $$\\rightarrow$$ <em>Yazıl-</em> (Yeni Fiil)</li></ul></li></ul><hr><h2 id="ozet" tabindex="-1">Özet <a class="header-anchor" href="#ozet" aria-label="Permalink to “Özet”">​</a></h2><p>Yapım ekleri, Türkçenin yaşayan hücresel fabrikalarıdır. Yeni bir icat, yeni bir duygu veya teknik bir terim ortaya çıktığında, Türkçe bu 4 ana gruptaki işlek ekleri kullanarak saniyeler içinde yepyeni ve tam oturan kelimeler üretebilir.</p><p>Yapım eklerinin mantığını kavradığımızda, Türkçenin kelime türetmedeki o sınırsız gücüne hayran kalmamak elde değildir.</p><p>Serimizin 10. bölümünde, kelimelerin anlamını değiştirmeyen ama onları cümle içinde yönetilebilir kılan hayati yapılara geçiyoruz: <strong>&quot;İsim Çekim Ekleri (Hâl ekleri, İyelik ekleri, Çoğul ekleri)&quot;</strong>.</p><p>Takipte kal aslanım, sayfa dönüyor!</p>',34)])])}const $=e(n,[["render",m]]);export{u as __pageData,$ as default};
